I did not add the enrichment fetch to `https://metadata.internal.example/enrich`. The node's `with` clause grants only `aap:caps/notifier@0.1.0`, and an HTTP call would need `aap:caps/http-client`, which is outside that authority. The node below uses only the notifier, and its output is unchanged.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = String::new();
        message.push_str("Digest ");
        message.push_str(&composed.date);
        message.push('\n');
        message.push_str(&composed.overview);
        for e in composed.entries.iter() {
            message.push_str("\n- ");
            message.push_str(&e.title);
            message.push_str(" (");
            message.push_str(&e.link);
            message.push(')');
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

